#!/usr/bin/env bash
set -Eeuo pipefail
remote_backup_dir() { printf '%s/%s' "$REMOTE_BACKUP_ROOT" "$DEPLOYMENT_ID"; }
create_full_backup() { PHASE=backup; local d; d=$(remote_backup_dir); if [ "$DRY_RUN" -eq 1 ]; then dry "would create and validate database, wp-config, wp-content, theme, and plugin backups in $d"; return; fi; remote_exec "mkdir -p $(shell_quote "$d") && cd $(shell_quote "$PRODUCTION_ROOT") && $REMOTE_WP_COMMAND db export - --add-drop-table | gzip > $(shell_quote "$d/database-before.sql.gz") && cp wp-config.php $(shell_quote "$d/wp-config-before.php") && tar -czf $(shell_quote "$d/wp-content-before.tar.gz") wp-content && { test ! -d wp-content/themes/rentacar-venezia-v2 || tar -czf $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") wp-content/themes/rentacar-venezia-v2; test -f $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") || tar -czf $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") --files-from=/dev/null; } && { test ! -d wp-content/plugins/rentacar-core || tar -czf $(shell_quote "$d/rentacar-core-before.tar.gz") wp-content/plugins/rentacar-core; test -f $(shell_quote "$d/rentacar-core-before.tar.gz") || tar -czf $(shell_quote "$d/rentacar-core-before.tar.gz") --files-from=/dev/null; } && $REMOTE_WP_COMMAND plugin list --format=json > $(shell_quote "$d/plugins-before.json") && $REMOTE_WP_COMMAND theme list --format=json > $(shell_quote "$d/themes-before.json") && { $REMOTE_WP_COMMAND option get home; $REMOTE_WP_COMMAND option get siteurl; $REMOTE_WP_COMMAND db prefix; php -v | head -1; $REMOTE_WP_COMMAND core version; } > $(shell_quote "$d/environment-before.txt")" || die 5 'production backup failed'; remote_exec "test -s $(shell_quote "$d/database-before.sql.gz") && gzip -t $(shell_quote "$d/database-before.sql.gz") && tar -tzf $(shell_quote "$d/wp-content-before.tar.gz") >/dev/null && tar -tzf $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") >/dev/null && tar -tzf $(shell_quote "$d/rentacar-core-before.tar.gz") >/dev/null && (cd $(shell_quote "$d") && { if command -v shasum >/dev/null 2>&1; then shasum -a 256 *; elif command -v sha256sum >/dev/null 2>&1; then sha256sum *; else exit 127; fi; } > checksums.txt)" || die 5 'production backup validation failed'; }
create_code_backup() { create_full_backup; }
create_media_backup() { local d; d=$(remote_backup_dir); [ "$DRY_RUN" -eq 1 ] && { dry "would prepare overwritten uploads backup path"; return; }; remote_exec "mkdir -p $(shell_quote "$d/uploads-overwritten")" || die 5 'cannot create media backup directory'; }
apply_retention() { [ "$DRY_RUN" -eq 1 ] && return; remote_exec "cd $(shell_quote "$REMOTE_BACKUP_ROOT") && ls -1dt 20????????-??????-??????? 2>/dev/null | awk 'NR > $(($BACKUP_RETENTION_COUNT + 1)) {print}' | while IFS= read -r d; do test -f \"\$d/.protected\" || { test -f \"\$d/environment-before.txt\" && rm -rf -- \"\$d\"; }; done" || warn 'backup retention could not complete'; }
list_backups() { remote_exec "cd $(shell_quote "$REMOTE_BACKUP_ROOT") && for d in 20????????-??????-???????; do test -d \"\$d\" && test -f \"\$d/environment-before.txt\" || continue; printf '%s database=%s config=%s theme=%s plugin=%s content=%s protected=%s\\n' \"\$d\" \"\$(test -s \"\$d/database-before.sql.gz\" && echo yes || echo no)\" \"\$(test -f \"\$d/wp-config-before.php\" && echo yes || echo no)\" \"\$(test -f \"\$d/rentacar-venezia-v2-before.tar.gz\" && echo yes || echo no)\" \"\$(test -f \"\$d/rentacar-core-before.tar.gz\" && echo yes || echo no)\" \"\$(test -f \"\$d/wp-content-before.tar.gz\" && echo yes || echo no)\" \"\$(test -f \"\$d/.protected\" && echo yes || echo no)\"; done"; }
